\label{sec:setup}
Let $x $ and $y$ be random variables taking values in $\mathbb{R}^d$ and $\mathbb{R}$, respectively.
We consider the least-squares problem:
\begin{equation}\label{eq:least_squares}
\min_{\theta\in \mathbb{R}^d} f(\theta), \quad f(\theta) := \frac{1}{2} \mathbb{E}\left[(x ^\top \theta - y)^2\right],
\end{equation}
where the expectation is over the joint distribution of $(x , y)$ on $\mathbb{R}^d \times \mathbb{R}$.

\label{as:slock}
Set $\sigma>0$. Let $(\varepsilon_t)_{t\geq0}$ be a sequence of i.i.d.~random variables with zero mean and $\mathrm{Var}(\varepsilon_t)=\sigma^2$. Let $(\mu_t)_{t\geq0}$ be i.i.d. random vectors in $\mathbb{R}^d$, with distribution:
\begin{equation}
    \mu_t = r\, q_i, \quad i\sim \pi,
\end{equation}
where $\pi_i = \frac{\lambda_i}{\mathrm{Tr}(\Lambda)}$ for $i\in \{1,\dots,d\}$ and $r=\sqrt{\mathrm{Tr}(\Lambda)}$.

Let $(s_t)_{t\geq 0}$ be a sequence of i.i.d.~random variables satisfying $\mathbb{E}[s_t]=0$ and $s_t^2=1$ a.s.

We assume that $(\mu_t), (s_t)$ and $(\varepsilon_t)$ are mutually independent. At each step $t$, we draw $x _t := s_t \mu_t$ and $\varepsilon_t$.

\label{th:risk}
Let $m_0\in \mathbb{R}^d$ be the diagonal of $Q^\top(\theta_0-\theta_*) (\theta_0-\theta_*)^\top Q$.
Then, after $t$ steps of SGD, $t \in \{1,\dots,T\}$, the expected excess risk is given by:
\begin{equation}
    \mathcal R_{t\mid T} = B_{t\mid T} + V_{t\mid T}.
\end{equation}

\label{as:alphabeta}
There exist $\alpha>1, \beta>0$ and $L,\Delta>0$ such that for all $i \geq 1$, 
\begin{equation}
    m_{0,i} = \Delta i^{-\beta} \quad \text{and} \quad \lambda_i = L i^{-\alpha}.
\end{equation}

\label{as:eta}
We assume the base learning-rate $\gamma$ satisfies:
\begin{equation}\label{eq:eta}
   0 < \gamma < {2}\big/{\mathrm{Tr}(\Lambda)}.
\end{equation}

\label{th:constant}
Let $\eta_j = 1$ for all $j\geq 0$.
Under \cref{as:alphabeta} and \cref{as:eta}, as $T \to \infty$, we have
$B_T \sim \widetilde B_T$ and $V_T \to V_\infty$, where


\begin{equation}\label{eq:constant}
\begin{aligned}
\widetilde B_T &:= \frac{L\Delta}{2\alpha}\, \Gamma(\omega)
  \big((2-\gamma\mathrm{Tr}(\Lambda))L\gamma T\big)^{-\omega}, \\[-.05cm]
V_\infty &:= \frac{\zeta(\alpha)}{2}\,
  \frac{\sigma^2 L\gamma}{2-\gamma\mathrm{Tr}(\Lambda)}.
\end{aligned}
\end{equation}

\label{th:gammastar}
With $\widetilde\gamma^*_T$ defined as the minimizer of $\widetilde{\mathcal R}^{(0)}_T(\gamma)$, we obtain that the exact risk for the base learning-rate $\widetilde\gamma^*_T$ is asymptotically optimal (see more details in \cref{app:gammastar}):
\begin{equation}\label{eq:gammastar}
\inf_{\gamma \in (0, \gamma_{\max})} \mathcal R_T(\gamma) \sim \mathcal R_T(\widetilde{\gamma}^*_T),
  \qquad T \to \infty .
\end{equation}

Under \cref{as:alphabeta}, for a batch size $b$,
    \begin{equation}
    \left\{
    \begin{aligned}
        B_{t\mid T} &= \frac{1}{2} \sum_{i=1}^\infty \Delta Li^{-\alpha-\beta}  \prod_{j=0}^{t-1} \left[ 1-2\gamma\eta_j Li^{-\alpha}+\gamma^2\eta_j^2 \frac{\mathrm{Tr}(\Lambda)}{b}L i^{-\alpha} + \gamma^2\eta_j^2\frac{b-1}{b}L^2i^{-2\alpha}\right]
        \\
        V_{t\mid T} &= \frac{\sigma^2}{2 b} \sum_{i=1}^\infty  \sum_{k=0}^{t-1} L^2i^{-2\alpha}\gamma^2\eta_k^2  \prod_{j=k+1}^{t-1} \left[ 1-2\gamma\eta_j Li^{-\alpha}+\gamma^2\eta_j^2 \frac{\mathrm{Tr}(\Lambda)}{b}L i^{-\alpha} +\gamma^2 \eta_j^2\frac{b-1}{b}L^2i^{-2\alpha}\right]
    \end{aligned}
    \right.
    \end{equation}

\label{as:gamma_batch}
We assume that the base learning-rate $\gamma$ satisfies:
\begin{equation}\label{eq:gamma_batch}
    0 < \gamma < \frac{2 b}{\mathrm{Tr}(\Lambda) + L(b-1)}.
\end{equation}

\label{th:batch}
Under \cref{as:alphabeta} and \cref{as:gamma_batch}, as $T \to \infty$, with a batch size $b$:

\subparagraph{Constant schedule:}
\begin{equation}
\begin{aligned}
    B_T &   \sim \widetilde B_T := \frac{L\Delta}{2\alpha} \frac{\Gamma\left(\omega\right)}{(2\gamma(1-\frac{\gamma \mathrm{Tr}(\Lambda)}{2 b})L T)^{\omega}},
    \\
    V_T &\sim \widetilde V_T:= \frac{\gamma L\sigma^2}{4b} \sum_{i=1}^\infty \frac{1}{\left(1-\frac{\gamma \mathrm{Tr}(\Lambda)}{2 b} \right)i^{\alpha}-\frac{L\gamma}{2}\frac{b-1}{b}}.
\end{aligned}
\end{equation}



\subparagraph{WSD schedule:}

\begin{equation}
\begin{aligned}
    B_T &\sim \widetilde B_T := \frac{L\Delta}{2\alpha}
    \frac{\Gamma\!\left(\omega\right)}
    {\left[\gamma L T\!\left(2 - c - \frac{\gamma\mathrm{Tr}(\Lambda)}{b}\!\left(1 - \frac{2c}{3}\right)\right)
    \right]^{\omega}},
    \\[6pt]
    V_T &\sim \widetilde V_T:=
    \begin{cases}
    \displaystyle
    \begin{aligned}
    &\Bigg(
      \frac{(L\gamma)^{\frac{1}{\alpha}}\sigma^2}{2\alpha b \left( \frac{\gamma \mathrm{Tr}(\Lambda)}{b} - 2 \right)}
      \Gamma\!\left(\frac{\alpha-1}{\alpha}\right)
      \!\left[\kappa_1^{\frac{1-\alpha}{\alpha}} - \kappa_2^{\frac{1-\alpha}{\alpha}}\right]
      \\
      &+ \frac{L^2\gamma^2\sigma^2}{2\alpha b}
      \Gamma\!\left(2-\frac{1}{\alpha}\right)
      (\gamma L)^{\frac{1-2\alpha}{\alpha}}
      \mathcal{I}^{(b)}_{\alpha,\gamma}\,c^{\frac{1-\alpha}{\alpha}}
    \Bigg)T^{\frac{1-\alpha}{\alpha}}
    \end{aligned}
    & \text{if }\alpha<2,\\[14pt]
    \displaystyle
    \frac{\sqrt{\pi}}{8}\,L^{1/2}\gamma^{1/2}\frac{\sigma^2}{b}\,
    \zeta\!\left(\frac{\alpha}{2}\right)(cT)^{-1/2},
    & \text{if }\alpha>2.
    \end{cases}
\end{aligned}
\end{equation}

where we define
\[
\begin{array}{lll}
    \mathcal{I}^{(b)}_{\alpha,\gamma} := \int_0^1 x^{\frac{2-2\alpha}{\alpha}} \left(1-\frac{\gamma\mathrm{Tr}(\Lambda)}{3b}x\right)^{\frac{1-2\alpha}{\alpha}}dx, &
    \kappa_1 :=   2 - c - \frac{\gamma \mathrm{Tr}(\Lambda)}{b} \left( 1 - \frac{2c}{3} \right), &
    \kappa_2 := c \left(1-\frac{\gamma\mathrm{Tr}(\Lambda)}{3b}\right).
\end{array}
\]

\label{th:eta_star_batch} 
Let $\widetilde\gamma^*_{T,b}$ be the batch-scaled learning-rate as defined in \cref{eq:gamma_b_star}.
\begin{equation} 
 \inf_\gamma \mathcal R_T(\gamma) \sim \mathcal R_T(\widetilde\gamma^*_{T,b}) ,
  \qquad T \to \infty.
\end{equation}

\label{lemma:eta_star_to_0}
For a constant or WSD schedule:
\begin{enumerate}
    \item Every sequence of minimizers of $\gamma\mapsto \widetilde{\mathcal R}_T(\gamma)$ over the interval $(0, \gamma_{\max})$ tends to $0$ as $T\to \infty$,
    \item $\displaystyle \widetilde{\gamma}^*_T := \operatorname*{argmin}_{\gamma \in (0, \gamma_{\max})} \widetilde{\mathcal R}^{(0)}_T(\gamma) = \Theta(T^{-\vartheta})$ with $\vartheta:= \frac{\omega - r}{v+\omega} \in (0,1)$,
    \item $\displaystyle \widetilde{\mathcal R}_T(\widetilde{\gamma}^*_T) \;\sim\; \inf_{\gamma \in (0, \gamma_{\max})} \widetilde{\mathcal R}_T(\gamma),
      \qquad T \to \infty$.
\end{enumerate}

\label{th:gammastar_appendix}
With $\widetilde\gamma^*_T$ defined as above, we obtain that the exact risk for the base learning-rate $\widetilde\gamma^*_T$ is asymptotically optimal:
\begin{equation}\label{eq:gammastar}
\inf_{\gamma \in (0, \gamma_{\max})} \mathcal R_T(\gamma) \sim \mathcal R_T(\widetilde{\gamma}^*_T),
  \qquad T \to \infty .
\end{equation}

\label{lemma:recurrence_gaussian} For $M_t = Q^\top\mathbb{E}[(\theta_t-\theta_*)(\theta_t-\theta_*)^\top]Q$, and $m_t = \left(M_{i,i}\right)_{i\geq 1} \in \mathbb{R}^d$ the diagonal of $M_t$,
\begin{equation}\label{eq:recurrence_gaussian}
m_{t+1} = \left[(I - \gamma\eta_t\Lambda)^2 + \gamma^2\eta_t^2 \Lambda^2 + \gamma^2\eta_t^2\lambda\lambda^\top \right] m_t + \gamma^2\eta_t^2 \sigma^2 \lambda, \qquad t \in\{0,...,T-1\}.
\end{equation}

\label{lemma:stability}
Let $L,\gamma >0$ and $\alpha>1$. Assume $S_i>Li^{-\alpha}$ for $i\geq1$. For $\eta \in \mathbb{R}$ and $i\geq 1$, let $P(\eta,i) := 1 - 2\gamma \eta L i^{-\alpha}+ \gamma^2 \eta^2L S_i i ^{-\alpha}$. The following are equivalent:
\begin{enumerate}
    \item[$(i)$] $\forall i \geq 1, \forall \eta \in (0,1], \quad 0\leq P(\eta,i) <1$,
    \item[$(ii)$] $ \forall i\geq1, \quad \gamma < \frac{2}{S_i}.$
\end{enumerate}


\begin{proof}
We fix $i\geq 1$.
Remark that the expression of $P$ is a second order polynomial in $\eta$.
It has a minimum reached at $\eta^0:=\frac{1}{\gamma S_i}$ and whose value is $P(\eta^0,i) = 1 - \frac{2 Li^{-\alpha}}{S_i} + \frac{Li^{-\alpha}}{S_i} = 1- \frac{Li^{-\alpha}}{S_i}$. Therefore since $S_i>Li^{-\alpha}$ and $i^{-\alpha}\leq 1$, $P(\eta,i)>0$ is always satisfied for $\eta\in \mathbb{R}$ and $i\geq 1$. We can therefore write $(i)$ as $\forall i \geq 1, \forall \eta \in (0,1], ~ P(\eta,i) < 1$.

Furthermore, $1-P(\eta,i) = 2\gamma \eta L i^{-\alpha}  - \gamma^2 \eta^2L S_i i ^{-\alpha} = \eta(2\gamma L i^{-\alpha}  - \gamma^2 \eta L S_i i ^{-\alpha} )$ so $1-P(\eta,i) = 0  \iff \eta \in \{0, \frac{2}{\gamma S_i}\}$. Since $1 - P(\eta, i)$ has a maximum in $\eta$,
\begin{equation}\label{eq:interval_eta}
\forall \eta \in \mathbb{R}, \quad 1-P(\eta,i) > 0 \iff \eta \in \left(0, \frac{2}{\gamma S_i}\right).
\end{equation}

\begin{itemize}
\item Suppose $(i)$. Choosing $\eta=1$, $1-P(1,i)>0$ so by \cref{eq:interval_eta}, $\forall i\geq1, 1<\frac{2}{\gamma S_i}$, which is $(ii)$.
\item Suppose $(ii)$. Then for every $i\geq 1$, $\frac{2}{\gamma S_i}>1$. Hence, for all $\eta \in (0,1]$, \cref{eq:interval_eta} gives $1 - P(\eta,i)>0$. $(i)$ is satisfied.
\end{itemize}


\end{proof}

We fix $i\geq 1$.
Remark that the expression of $P$ is a second order polynomial in $\eta$.
It has a minimum reached at $\eta^0:=\frac{1}{\gamma S_i}$ and whose value is $P(\eta^0,i) = 1 - \frac{2 Li^{-\alpha}}{S_i} + \frac{Li^{-\alpha}}{S_i} = 1- \frac{Li^{-\alpha}}{S_i}$. Therefore since $S_i>Li^{-\alpha}$ and $i^{-\alpha}\leq 1$, $P(\eta,i)>0$ is always satisfied for $\eta\in \mathbb{R}$ and $i\geq 1$. We can therefore write $(i)$ as $\forall i \geq 1, \forall \eta \in (0,1], ~ P(\eta,i) < 1$.

Furthermore, $1-P(\eta,i) = 2\gamma \eta L i^{-\alpha}  - \gamma^2 \eta^2L S_i i ^{-\alpha} = \eta(2\gamma L i^{-\alpha}  - \gamma^2 \eta L S_i i ^{-\alpha} )$ so $1-P(\eta,i) = 0  \iff \eta \in \{0, \frac{2}{\gamma S_i}\}$. Since $1 - P(\eta, i)$ has a maximum in $\eta$,
\begin{equation}\label{eq:interval_eta}
\forall \eta \in \mathbb{R}, \quad 1-P(\eta,i) > 0 \iff \eta \in \left(0, \frac{2}{\gamma S_i}\right).
\end{equation}

\begin{itemize}
\item Suppose $(i)$. Choosing $\eta=1$, $1-P(1,i)>0$ so by \cref{eq:interval_eta}, $\forall i\geq1, 1<\frac{2}{\gamma S_i}$, which is $(ii)$.
\item Suppose $(ii)$. Then for every $i\geq 1$, $\frac{2}{\gamma S_i}>1$. Hence, for all $\eta \in (0,1]$, \cref{eq:interval_eta} gives $1 - P(\eta,i)>0$. $(i)$ is satisfied.
\end{itemize}

\label{lemma:recurrence} For $M_t = Q^\top\mathbb{E}[(\theta_t-\theta_*)(\theta_t-\theta_*)^\top]Q$, and $m_t = \left(M_{i,i}\right)_{i\geq 1} \in \mathbb{R}^d$ the diagonal of $M_t$,
\begin{equation}\label{eq:recurrence}
m_{t+1} = \left[I + (-2\gamma\eta_t   + \gamma^2\eta_t^2 \mathrm{Tr} (\Lambda)) \Lambda  \right]m_t + \gamma^2\eta_t^2\sigma^2\lambda, \qquad t \in\{0,...,T-1\}.
\end{equation}

\label{th:risk_alpha_beta}
    Under \cref{as:alphabeta}, we have
    \begin{equation}\left\{
    \begin{aligned}
        B_{t \mid T} &= \frac{1}{2} \sum_{i=1}^d \Delta Li^{-\alpha-\beta}  \prod_{k=0}^{t-1} \left[ 1-2\gamma\eta_k Li^{-\alpha}+\gamma^2\eta_k^2 \mathrm{Tr}(\Lambda)L i^{-\alpha} \right],
        \\
        V_{t \mid T} &= \frac{1}{2} \sum_{i=1}^d  \sum_{k=0}^{t-1} L^2i^{-2\alpha}\gamma^2\eta_k^2 \sigma^2 \prod_{j=k+1}^{t-1} \left[ 1-2\gamma\eta_j Li^{-\alpha}+\gamma^2\eta_j^2 \mathrm{Tr}(\Lambda)L i^{-\alpha} \right].
    \end{aligned}\right.
    \end{equation}

\label{th:tauberian}
         Let $(u_k)$ be a real-valued sequence such that the series $U(z) = \sum_{k=0}^\infty u_kz^k$ is defined on the interval $[0,1)$. Let $\mu \in \mathbb N$ and $p>0$. Then, if there exists a constant $K\in \mathbb{R}$ such that $\forall k\geq 1, k^{2+\mu-p}(u_k - u_{k-1})\leq K$, and $\lim_{z\to 1^-} (1-z)^p U^{(\mu)}(z)$ exists, then $\lim_{k \to +\infty} k^{1+\mu-p} u_k$ exists and
         \begin{equation}\label{th:korevaar}
            \lim_{z \to 1^-} (1 - z)^p U^{(\mu)}(z) = \Gamma(p) \cdot \lim_{k \to +\infty} k^{1+\mu-p} u_k.
         \end{equation}

\begin{align*}
\Pi_{T,i}
&= \prod_{j=0}^{T-1}
   \left[1 - 2\frac{L}{i^\alpha}
   \!\left(\gamma\eta_j - \frac{\gamma^2\eta_j^2\operatorname{tr}(\Lambda)}{2}\right)\right] ,
   \\
&= \left(1 - A^{(1)}_i + A^{(2)}_i\right)^{(1-c)T+1}
   \prod_{j=(1-c)T+1}^{T-1}
   \left(1 - A^{(1)}_i\frac{T-j}{cT} + A^{(2)}_i\!\left(\frac{T-j}{cT}\right)^{\!2}\right).
\end{align*}

Set $\ell = j-(1-c)T$ (from $1$ to $cT-1$), so $\dfrac{T-j}{cT} = 1 - \dfrac{\ell}{cT}$.
Then set $p = cT - \ell$ (from $cT-1$ to $1$), so $1 - \dfrac{\ell}{cT} = \dfrac{p}{cT}$.
\[
\sum_{j=(1-c)T+1}^{T-1}
\log\!\left(1 - A^{(1)}_i\frac{T-j}{cT}+A^{(2)}_i\!\left(\frac{T-j}{cT}\right)^{\!2}\right)
= \sum_{p=1}^{cT-1}
  \log\!\left(1 - A^{(1)}_i\frac{p}{cT}+A^{(2)}_i\!\left(\frac{p}{cT}\right)^{\!2}\right).
\]
By Euler–-Maclaurin ($\sum_{p=1}^{cT-1}$ has boundary values $f(0)=0$, $f(1)=\log(1-A^{(1)}_i+A^{(2)}_i)$):
\[
\sum_{p=1}^{cT-1}
\log\!\left(1-A^{(1)}_i\frac{p}{cT}+A^{(2)}_i\!\left(\frac{p}{cT}\right)^{\!2}\right)
= cT\!\int_0^1\!\log\!\left(1-A^{(1)}_ix+A^{(2)}_ix^2\right)dx
   {- \frac{\log(1-A^{(1)}_i+A^{(2)}_i)}{2}+O\left(\frac{1}{i^\alpha T}\right)}.
\]
Then we can write:
\begin{align*}
\Pi_{T,i}
&= S_{i,T}\exp\!\left[
  (1-c)T\log(1-A^{(1)}_i+A^{(2)}_i)
  + cT\!\int_0^1\!\log\!\left(1-A^{(1)}_ix+A^{(2)}_ix^2\right)dx
\right],
\end{align*}
with $S_{i,T} = \sqrt{1-A^{(1)}_i+A^{(2)}_i}(1+O(\tfrac{1}{i^\alpha T}))$. Let $S_i := \lim_{T\to\infty }S_{i,T} = \sqrt{1-A^{(1)}_i+A^{(2)}_i}$.
\paragraph{Bias.}
The method is identical to the linear schedule, with
\[
I_i = (1-c)\log(1-A^{(1)}_i+A^{(2)}_i)
    + c\!\int_0^1\!\log\!\left(1-A^{(1)}_ix+A^{(2)}_ix^2\right)dx.
\]
For $i$ large, $I_i \sim -i^{-\alpha}\gamma  L\kappa(c)$
with $\kappa(c) = 2-c-\gamma \mathrm{Tr}(\Lambda)(1-\frac{2c}{3})$,
so the Tauberian argument gives
\[
B_T \sim \frac{L\Delta}{2\alpha}
\frac{\Gamma\!\left(\frac{\beta-1}{\alpha}+1\right)}
{\left[\gamma  LT\!\left(2-c-\gamma \mathrm{Tr}(\Lambda)\!\left(1-\frac{2c}{3}\right)\right)
\right]^{\frac{\beta-1}{\alpha}+1}}.
\]

\paragraph{Variance.}
\begin{align*}
V_T
&= \frac{1}{2}\sum_{i=1}^\infty \sum_{k=0}^{T-1}
   \frac{L^2}{i^{2\alpha}}\gamma^2\eta_k^2\sigma^2
   \prod_{m=k+1}^{T-1}\!\left[1-2\bar\nu_m\frac{L}{i^\alpha}\right]
= V_T^A + V_T^B,
\end{align*}
where $V_T^A$ (resp.\ $V_T^B$) sums over $k \le (1-c)T$ (constant phase)
and $k > (1-c)T$ (cooldown phase).

\subparagraph{Constant part: $V_T^A$.}
For the cooldown product from $m=(1-c)T+1$ to $T-1$,
set $\ell=T-m$ (from $cT-1$ to $1$); then $\eta_m = \ell/(cT)$
and the factor is $1-A^{(1)}_i\ell/(cT)+A^{(2)}_i(\ell/(cT))^2$. Let $S_i^A := (1-A^{(1)}_i+A^{(2)}_i)^{-1/2}\xrightarrow{i\to\infty}1$. Hence

\begin{align*}
V_T^A
&= \frac{1}{2}\sum_{i=1}^\infty \sum_{k=0}^{(1-c)T}
   \frac{L^2\gamma ^2\sigma^2}{i^{2\alpha}}
   [1-A^{(1)}_i+A^{(2)}_i]^{(1-c)T-k}
   \exp\!\left[\sum_{\ell=1}^{cT-1}
   \log\!\left(1-A^{(1)}_i\frac{\ell}{cT}+A^{(2)}_i\!\left(\frac{\ell}{cT}\right)^{\!2}\right)\right],
\\
&\sim
\frac{1}{2}\sum_{i=1}^\infty \sum_{k=0}^{(1-c)T}
   \frac{L^2\gamma ^2\sigma^2}{i^{2\alpha}}
   [1-A^{(1)}_i+A^{(2)}_i]^{(1-c)T-k}
   \frac{1}{\sqrt{1-A^{(1)}_i+A^{(2)}_i}}
   \exp\!\left[cT\!\int_0^1\!\log\!\left(1-A^{(1)}_ix+A^{(2)}_ix^2\right)dx\right],
\\
&\sim
\frac{1}{2}\sum_{i=1}^\infty \frac{L^2\gamma ^2\sigma^2}{i^{2\alpha}}
   \frac{[1-A^{(1)}_i+A^{(2)}_i]^{(1-c)T+1}-1}{(1-A^{(1)}_i+A^{(2)}_i)-1}\,S_i^A
   \exp\!\left[cT\!\int_0^1\!\log\!\left(1-A^{(1)}_ix+A^{(2)}_ix^2\right)dx\right].
\end{align*}
With $A^{(1)}_i=A^{(1)} i^{-\alpha}$, $A^{(2)}_i=A^{(2)} i^{-\alpha}$,
$J_i=\int_0^1\log(1-A^{(1)}_iu+A^{(2)}_iu^2)du = A^{(J)} i^{-\alpha}+O(i^{-2\alpha})$ for $i\gg 1$,
\[
V_T^A \sim
\frac{L^2\gamma ^2\sigma^2}{2(A^{(2)}-A^{(1)})}
\sum_{i=1}^\infty i^{-\alpha} S_i^A
\left[(1-A^{(1)}_i+A^{(2)}_i)^{(1-c)T+1}e^{cJ_iT} - e^{cJ_iT}\right].
\]
The $z$-transform is
\begin{align*}
\mathcal{V}^A(z) = \frac{L^2\gamma ^2\sigma^2}{2(A^{(2)}-A^{(1)})}
\sum_{i=1}^\infty i^{-\alpha} S_i^A
&\left[
  \frac{1-A^{(1)}_i+A^{(2)}_i}{1-z(1-A^{(1)}_i+A^{(2)}_i)^{1-c}e^{cJ_i}}
  - \frac{1}{1-ze^{cJ_i}}
\right],
\\=
\frac{L^2\gamma ^2\sigma^2}{2(A^{(2)}-A^{(1)})}
\sum_{i=1}^\infty i^{-\alpha} S_i^A
&\bigg[
  \frac{1+(-A^{(1)}+A^{(2)})i^{-\alpha}}{1-z(1-A^{(1)}_i+A^{(2)}_i)^{1-c}(1+cA^{(J)} i^{-\alpha} +O(i^{-2\alpha}))}
  \\
  &- \frac{1}{1-z(1+cA^{(J)} i^{-\alpha} +O(i^{-2\alpha}))}
\bigg].
\end{align*}
Using
$\log(1-A^{(1)}_i+A^{(2)}_i) = (A^{(2)}-A^{(1)})i^{-\alpha}+O(i^{-2\alpha})$,
$\exp(cJ_i) = 1+cA^{(J)} i^{-\alpha}+O(i^{-2\alpha})$,
the two poles are $\kappa_1 = (A^{(1)}-A^{(2)})(1-c)-cA^{(J)} $ and $\kappa_2=-cA^{(J)} $.

\begin{align*}
\mathcal{V}^A(1-s) 
&=
\frac{L^2\gamma ^2\sigma^2}{2(A^{(2)}-A^{(1)})}
\sum_{i=1}^\infty i^{-\alpha}
\left[
  \frac{1}{s+(1-s)\kappa_1i^{-\alpha} +O(i^{-2\alpha})}
  - \frac{1}{s+(1-s)\kappa_2i^{-\alpha} +O(i^{-2\alpha})}
\right],
\\&=
\frac{L^2\gamma ^2\sigma^2}{2(A^{(2)}-A^{(1)})}
\sum_{i=1}^\infty x_i^{-\alpha} s
\left[
  \frac{1}{s+(1-s)\kappa_1 x_i^{-\alpha} s +O(x_i^{-2\alpha} s^{2})}
  -  \frac{1}{s+(1-s)\kappa_2 x_i^{-\alpha} s +O(x_i^{-2\alpha} s^{2})}
  \right],
\\&=
\frac{L^2\gamma ^2\sigma^2}{2(A^{(2)}-A^{(1)})} s^{-1/\alpha}
\sum_{i=1}^\infty x_i^{-\alpha} 
\bigg[
  \frac{1}{1+(1-s)\kappa_1 x_i^{-\alpha}  +O(x_i^{-2\alpha} s)}
  \\& \qquad -  \frac{1}{1+(1-s)\kappa_2 x_i^{-\alpha}  +O(x_i^{-2\alpha} s)}
  \bigg] s^{1/\alpha}.
\end{align*}

With $x_i =is^{1/\alpha}$, $\Delta x = s^{1/\alpha}$.

By the DCT we can replace the sum by an integral over $[0,\infty)$:
\begin{align*}
\mathcal{V}^A(1-s)
&\sim \frac{L^2\gamma ^2\sigma^2}{2(A^{(2)}-A^{(1)})} s^{-1/\alpha}
  \int_0^\infty x^{-\alpha}
  \!\left[\frac{1}{1+\kappa_1 x^{-\alpha}}
         -\frac{1}{1+\kappa_2 x^{-\alpha}}\right]dx,
\\&\sim
\frac{L^2\gamma ^2\sigma^2}{2\alpha(A^{(2)}-A^{(1)})}
\,\Gamma\!\left(\tfrac{1}{\alpha}\right)\Gamma\!\left(1-\tfrac{1}{\alpha}\right)
